    if ($name === '' || strlen($phone) !== 10 || !array_key_exists($course, $courses) || $address === '' || strlen($password) < 6 || ($email !== '' && !filter_var($email, FILTER_VALIDATE_EMAIL))) $error = 'Please complete all required fields with valid information.';
