?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Registration | kgnst.com</title><link rel="stylesheet" href="assets/style.css"><style>.course-detail{display:none;grid-column:1/-1;background:#e7f4f1;border-left:4px solid #20d7c1;padding:15px 17px;font-size:14px;line-height:1.65;color:#27475b}.course-detail strong{display:block;color:#10233c;margin-bottom:4px}.course-detail.show{display:block}</style></head><body>
<nav><a class="brand" href="index.php"><span class="mark">◆</span>kgnst.com</a><a class="text-link" href="index.php">← Back to home</a></nav><main class="register-layout"><section class="intro"><span class="eyebrow">ADMISSIONS OPEN</span><h1>Create your <em>student</em> account.</h1><p>Complete the form to receive your unique kgnst.com registration number. Keep it safe—it is your student reference.</p><ol><li>Enter your details and choose a course.</li><li>Review the course details shown below.</li><li>Receive your registration number.</li></ol></section><section class="form-card"><?php if ($registration): ?><div class="success"><span class="eyebrow">REGISTRATION CREATED</span><h2>Welcome, <?=esc($_POST['full_name'])?>.</h2><p>Your kgnst.com registration number is</p><strong><?=$registration?></strong><p>Save this number and call <a href="tel:<?=INSTITUTE_PHONE?>">9839654910</a> to confirm your admission.</p><a class="button" href="registration.php">Register another student</a></div><?php else: ?><h2>Student registration</h2><p>All fields marked with * are required.</p><?php if ($error): ?><div class="alert error"><?=esc($error)?></div><?php endif; ?><form method="post"><div class="fields"><label class="full">Student full name *<input name="full_name" required autocomplete="name" value="<?=esc($_POST['full_name'] ?? '')?>"></label><label>Mobile number *<input name="phone" required pattern="[0-9]{10}" inputmode="numeric" autocomplete="tel" placeholder="10-digit mobile number" value="<?=esc($_POST['phone'] ?? '')?>"></label><label>Email address<input type="email" name="email" autocomplete="email" value="<?=esc($_POST['email'] ?? '')?>"></label><label>Course interested in *<select name="course" id="course" required><option value="">Select a course</option><?php foreach ($courses as $name => $detail): ?><option value="<?=esc($name)?>" <?=($_POST['course'] ?? '') === $name ? 'selected' : ''?>><?=esc($name)?></option><?php endforeach; ?></select></label><label>Create password *<input type="password" name="password" required minlength="6" autocomplete="new-password" placeholder="At least 6 characters"></label><div class="course-detail" id="course-detail" aria-live="polite"></div><label class="full">Address *<input name="address" required autocomplete="street-address" value="<?=esc($_POST['address'] ?? '')?>"></label></div><label class="check"><input type="checkbox" required> I confirm that my information is correct and agree to be contacted about admission.</label><button>Create registration</button></form><?php endif; ?></section></main><footer><span>© <?=date('Y')?> <?=APP_NAME?></span><span>Sikahari Nahar, Ghazipur, Uttar Pradesh</span><a href="admin.php">Admin login</a></footer><script>const details=<?=json_encode($courses, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,select=document.getElementById('course'),box=document.getElementById('course-detail');function showCourse(){const course=select.value;if(!course){box.classList.remove('show');box.innerHTML='';return}box.innerHTML='<strong>'+course+' Course Details</strong>'+details[course];box.classList.add('show')}select.addEventListener('change',showCourse);showCourse();</script></body></html>
